(async()=>{
"use strict";
// URL parsers may silently remove embedded tabs/newlines or rewrite backslashes.
function cleanInput(value,label){
 const text=String(value??"").trim();
 if(/[\s\p{Cc}\p{Cf}\\]/u.test(text))throw new Error(label+"含有空格、不可见字符或反斜杠，请重新粘贴。");
 return text;
}
function fieldsFromOptions(options={}){
 const proxy=options.proxy;
 const timeout=Number.isFinite(options.timeoutMs)?options.timeoutMs:1800000;
 return {mode:typeof proxy==='string'&&proxy.trim()==="direct"?"direct":typeof proxy==='string'&&proxy.trim()&&proxy.trim()!=="inherit"?"proxy":"inherit",proxy:typeof proxy==='string'&&!['direct','inherit'].includes(proxy.trim())?proxy.trim():"",seconds:String(timeout/1000),cache:options.continuationCache!==false,relayEnabled:options.relayEnabled===true,relayUrl:typeof options.relayUrl==='string'?options.relayUrl.trim():'',relayToken:typeof options.relayToken==='string'?options.relayToken.trim():''};
}
function optionsFromFields(fields,base={}){
 const secondsText=String(fields.seconds??"").trim(),seconds=/^\d+$/.test(secondsText)?Number(secondsText):NaN;
 if(!Number.isSafeInteger(seconds)||seconds<1||seconds>3600)throw new Error("超时须为 1–3600 秒的整数。");
 let proxy;
 const mode=String(fields.mode||'').trim();
 if(mode==="inherit")proxy="inherit";
 else if(mode==="direct")proxy="direct";
 else if(mode==="proxy"){
   const input=cleanInput(fields.proxy,"代理地址");let parsed;try{parsed=new URL(input);}catch{throw new Error("请输入有效的 HTTP(S) 代理地址。");}
   if(!["http:","https:"].includes(parsed.protocol)||!parsed.hostname||parsed.search||parsed.hash||!['','/'].includes(parsed.pathname))throw new Error("插件独立代理只接受 HTTP(S)；SOCKS 请在 Magpie 中配置并选择继承。");
   proxy=parsed.href;
 }else throw new Error("无效的代理模式。");
 if(typeof fields.cache!=="boolean")throw new Error("请选择是否启用会话缓存。");
 const relayEnabled=fields.relayEnabled===true;
 let relayUrl=String(fields.relayUrl||'').trim(),relayToken=String(fields.relayToken||'').trim();
 if(relayEnabled){
   relayUrl=cleanInput(relayUrl,'中继地址'); relayToken=cleanInput(relayToken,'访问密钥');
   let url;try{url=new URL(relayUrl);}catch{throw new Error('请输入有效的 WSS 中继地址。');}
   if(url.protocol!=='wss:'||!url.hostname||url.pathname!=='/relay'||url.username||url.password||/[?#]/.test(relayUrl))throw new Error('中继地址须为 wss://域名/relay，不含用户名或查询参数。');
   if(!/^[A-Za-z0-9_-]{32,256}$/.test(relayToken))throw new Error('请输入有效的中继访问密钥。');
   relayUrl=url.href;
 }
 const {models:_obsolete,...preserved}=base;
 return {...preserved,timeoutMs:seconds*1000,proxy,continuationCache:fields.cache,relayEnabled,relayUrl,relayToken};
}


const element=id=>document.getElementById(id);
let saved={};
function bounded(request){
 let timer;
 return Promise.race([request,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error("Magpie 未在限时内确认。请点“重新读取”核对结果。")),10000);})]).finally(()=>clearTimeout(timer));
}
const fieldIds=["mode","proxy","seconds","relayUrl","relayToken"];
function currentFields(){return {...Object.fromEntries(fieldIds.map(key=>[key,element(key).value])),cache:element("cache").checked,relayEnabled:element('relayEnabled').checked};}
function networkNote(){
 const mode=element("mode").value;element("proxy-row").hidden=mode!=="proxy";
 element("network-note").textContent=element("relayEnabled").checked?"启用 WSS 后，插件直接连接中继，不使用 HTTP 代理。":mode==="inherit"?"使用 Magpie 各入口的代理设置。":mode==="direct"?"API 请求直接连接。":"用于授权换票、推理与额度请求。";
}
function announce(message,error=false,state=error?"error":"idle"){
 const status=element("status");
 status.textContent=message;
 status.dataset.error=String(error);
 status.dataset.state=state;
 status.setAttribute("aria-busy",state==="saving"?"true":"false");
}
function relayNote(){element('relay-fields').hidden=!element('relayEnabled').checked;networkNote();}
async function load(){
 try{
  saved=await bounded(magpie.options.get())||{};
  const fields=fieldsFromOptions(saved);
  for(const [key,value]of Object.entries(fields)){if(key==="cache"||key==='relayEnabled')element(key).checked=value;else element(key).value=value;}
  relayNote();announce("已读取当前设置。修改后请点击“保存”。",false,"loaded");
 }catch(error){announce("读取设置失败："+(error.message||"Magpie 未返回配置。"),true);throw error;}
}
element("mode").addEventListener("change",networkNote);
element('relayEnabled').addEventListener('change',relayNote);
for(const id of ["mode","proxy","seconds","relayUrl","relayToken","cache","relayEnabled"]){
 element(id).addEventListener("input",()=>{element("probe-panel").hidden=true;announce("有未保存的修改。",false,"dirty");});
 element(id).addEventListener("change",()=>announce("有未保存的修改。",false,"dirty"));
}
async function testRelay(){
 const fields=currentFields(),next=optionsFromFields(fields,saved);
 if(!next.relayEnabled)throw new Error("请先勾选“手动启用 WSS 中继”并保存。");
 const expected=fieldsFromOptions(next),actual=fieldsFromOptions(saved);
 for(const key of ["relayEnabled","relayUrl","relayToken"]){if(actual[key]!==expected[key])throw new Error("请先保存当前中继配置，再开始测试。");}
 const id=Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,"0")).join("");
 const test={id,at:Date.now()};
 const host=await bounded(magpie.options.get())||{};
 if(["relayEnabled","relayUrl","relayToken"].some(k=>host[k]!==saved[k]))throw new Error("配置已改变，请重新读取。");
 await bounded(magpie.options.set({...host,relayTest:test}));
 saved={...host,relayTest:test};
 await showProbe(test);
}
async function showProbe(test){
 const img=element("probe-image"),button=element("testRelay");button.disabled=true;
 element("probe-panel").hidden=false;img.hidden=true;
 announce("正在测试 WSS… 握手后测量三次往返。",false,"testing");
 const until=Date.now()+95000;
 try{
  // The host serves its own page images in the sandbox. Result cards contain
  // only public status text and timings, with a separate name per test.
  for(let i=0;Date.now()<until;i++){
   const received=await new Promise(resolve=>{
    const timeout=setTimeout(()=>settle(false),2000);
    function settle(ok){clearTimeout(timeout);img.onload=img.onerror=null;resolve(ok);}
    img.onload=()=>settle(true);img.onerror=()=>settle(false);
    img.src="probe-results/"+test.id+".svg?read="+i;
   });
   if(received){img.hidden=false;announce("测试已完成。",false,"tested");return;}
   await new Promise(resolve=>setTimeout(resolve,700));
  }
  throw new Error("没有收到本次结果。请确认 BPS 已启用且插件目录可写，再重试。");
 }finally{img.onload=img.onerror=null;button.disabled=false;}
}
let busy=false;
element("testRelay").addEventListener("click",async()=>{
 if(busy||globalThis.bpsResetBusy)return;busy=true;globalThis.bpsSettingsBusy=true;element("controls").disabled=true;
 try{await testRelay();}catch(error){element("probe-panel").hidden=true;announce("WSS 测试失败："+(error.message||"未能完成测试。"),true,"error");}
 finally{busy=false;globalThis.bpsSettingsBusy=false;element("controls").disabled=false;}
});
element("reload").addEventListener("click",()=>load().catch(e=>announce(e.message,true)));
element("save").addEventListener("click",async ()=>{
 if(busy||globalThis.bpsResetBusy)return;
 globalThis.bpsSettingsBusy=true;
 try{
  const fields=currentFields(),next=optionsFromFields(fields,saved);
  delete next.relayTest;delete next.relayProbeId;delete next.bpsPanelAction;
  element("controls").disabled=true;announce("正在保存设置…",false,"saving");
  await bounded(magpie.options.set(next));
  const confirmed=await bounded(magpie.options.get())||{};
  if(!Object.keys(next).every(key=>Object.hasOwn(confirmed,key)))throw new Error("Magpie 未确认保存，请重新读取设置。");
  const expected=fieldsFromOptions(next),actual=fieldsFromOptions(confirmed);
  for(const key of ["mode","proxy","seconds","cache","relayEnabled","relayUrl","relayToken"]){
   if(actual[key]!==expected[key])throw new Error("Magpie 未确认保存，请重试。");
  }
  saved=confirmed;
  for(const key of fieldIds)element(key).value=actual[key];
  const reloadHint=expected.relayEnabled?"已保存并确认。请在插件列表关闭后重新启用 BPS，新的 WSS 路由才会生效。":"已保存并确认。请在插件列表关闭后重新启用 BPS，使网络设置生效。";
  announce(reloadHint,false,"saved");
 }catch(error){announce("保存失败："+(error.message||"Magpie 未接受配置。"),true,"error");}finally{globalThis.bpsSettingsBusy=false;element("controls").disabled=false;}
});
let readyTimer;
try{
 if(!globalThis.magpie?.options)throw new Error("未能连接 Magpie，请从插件设置页打开或重新载入页面。");
 await Promise.race([magpie.ready,new Promise((_,reject)=>{readyTimer=setTimeout(()=>reject(new Error("连接 Magpie 超时，请重新打开 BPS 设置；仍失败时关闭后重新启用此插件。")),10000);})]);
 await load();element("controls").disabled=false;
}catch(error){announce(error.message||"无法连接 Magpie，请从插件设置页打开。",true);}finally{clearTimeout(readyTimer);}

})();
